import { randomUUID } from "node:crypto";
import { expect, test } from "@playwright/test";
import { assertLocalApi, readProposalPdf, removeTestDocument } from "../test-utils/real-api";

// The whole-document map is generated by the local LLM: allow several minutes.
test.setTimeout(15 * 60_000);

test("completes the real PDF to map to tutor flow", async ({ page }, testInfo) => {
  test.skip(!process.env.COGNIFLOW_INTEGRATION_URL, "Requer FastAPI, pgvector e Ollama locais.");
  assertLocalApi(process.env.COGNIFLOW_INTEGRATION_URL!);

  const name = `cogniflow-stage6-${randomUUID()}.pdf`;
  const bytes = await readProposalPdf();

  try {
    await page.goto("/");
    await expect(page.getByLabel("Arquivo PDF")).toBeEnabled({ timeout: 120_000 });
    await page.getByLabel("Arquivo PDF").setInputFiles({ name, mimeType: "application/pdf", buffer: bytes });
    await page.getByRole("button", { name: "Enviar PDF" }).click();

    const canvas = page.getByRole("region", { name: "Mapa mental interativo" });
    await expect(canvas).toBeVisible({ timeout: 14 * 60_000 });
    await expect(canvas.locator('.react-flow__node[data-id="node-root"]')).toBeVisible();

    await page.getByRole("button", { name: "Lista", exact: true }).click();
    await page.getByRole("button", { name: "Abrir todos os eixos" }).click();
    expect(await page.getByRole("list", { name: "Eixos de estudo" }).locator(":scope > li").count()).toBeGreaterThanOrEqual(1);

    await page.getByLabel("Sua dúvida").fill("Qual é o objetivo do CogniFlow AI?");
    await page.getByRole("button", { name: "Perguntar" }).click();
    await expect(page.getByRole("article", { name: "Resposta do tutor" })).toBeVisible({ timeout: 5 * 60_000 });
    await page.screenshot({ path: testInfo.outputPath("fluxo-real.png"), fullPage: true });
  } finally {
    await removeTestDocument(name);
  }
});
